  // Función para decodificar entidades HTML
  function decodeHtmlEntities(text) {
    const parser = new DOMParser();
    const dom = parser.parseFromString(`<!doctype html><body>${text}`, 'text/html');
    return dom.body.textContent;
  }
  
  // Función para obtener categorías únicas con tildes corregidas
  function getUniqueCategoriesWithTildesFixed(data) {
    const categorySet = new Set();
  
    // Recorremos el arreglo 'response'
    data.response.forEach(product => {
      const category = product.categorias.trim(); // Obtenemos y limpiamos la categoría
      const decodedCategory = decodeHtmlEntities(category); // Decodificamos las entidades HTML
      categorySet.add(decodedCategory); // Añadimos la categoría al conjunto
    });
  
    // Convertimos el conjunto a un array
    return Array.from(categorySet);
  }
  
  // Ejecutar la función
  const uniqueCategoriesList = getUniqueCategoriesWithTildesFixed(data);
  console.log(uniqueCategoriesList);
  